def check_handoff_scope_note(ws):
    with sqlite3.connect(_db(ws)) as con:
        row = con.execute(
            "SELECT handoff_note FROM action_handoff WHERE decision_id = ? AND jira_issue_id = ?",
            ("DEC-2025-003", "ICT-2491")
        ).fetchone()
    if row is None:
        return {"score": 0, "detail": "target handoff is missing"}
    note = _norm(row[0])
    # Accept equivalent Chinese wording such as “可预测的标准服务请求” while retaining all boundary checks below.
    predictable = any(x in note for x in ("predictable request", "predictable requests", "可预测请求", "可预测服务请求", "可预测的服务请求", "可预测的标准服务请求", "已登记且可预测"))
    unknown = any(x in note for x in ("unknown", "unknown_problem", "未知问题"))
    response = any(x in note for x in ("response", "响应"))
    update = any(x in note for x in ("update", "updates", "更新"))
    diagnostic = any(x in note for x in ("diagnostic", "diagnosis", "诊断", "责任"))
    hard_limit = any(x in note for x in ("hard resolution", "deterministic resolution", "fixed resolution", "硬性解决", "硬解决", "解决时限"))
    if predictable and unknown and response and update and diagnostic and hard_limit:
        return {"score": 1, "detail": "note scopes the handoff to predictable requests and excludes unknown problems from a hard resolution time"}
    return {"score": 0, "detail": "note does not contain the required predictable-request scope and unknown-problem boundary"}


