        mismatches.append(f"source_system={row['source_system']!r}")
    metadata = " ".join(_norm(row[key]) for key in ("object_name", "storage_uri"))
    for token in (
        "3号楼",
        "消防栓箱门闭合不严",
        "GN-BGY-202410-XJ-011",
        "GN-BGY-202410-PH-011",
    ):
        if _norm(token) not in metadata:
            mismatches.append(f"business metadata missing {token}")
    if not any(token in metadata for token in ("2024-10-28", "20241028")):
        mismatches.append("business metadata missing 2024-10-28")
    rectification_complete = "整改完成" in metadata and any(
        token in metadata for token in ("复查通过", "符合销号条件")
    )
    if not rectification_complete and "整改复查通过" not in metadata:
        mismatches.append("business metadata missing 整改完成/复查通过")
    for key in ("evidence_no", "mime_type", "storage_uri", "captured_at", "checksum", "checksum_family", "registered_by"):
        if not str(row[key] or "").strip():
            mismatches.append(f"{key} blank")
