        with _db(ws) as con:
            no_count = con.execute(
                "SELECT COUNT(*) FROM evidence_objects WHERE evidence_no=?",
                (row["evidence_no"],),
            ).fetchone()[0]
        if no_count != 1:
            mismatches.append(f"global evidence_no count={no_count}")
    if mismatches:
        return {"score": 0, "detail": "; ".join(mismatches)}
    return {"score": 1, "detail": "one valid target object registered with Maximo provenance and required business metadata"}


