from datetime import datetime
from pathlib import Path
from zoneinfo import ZoneInfo
import sqlite3

TARGET_GRANT_ID = "GRT-2025-DA017-001"
TARGET_TASK_ID = "RVT-2025-DA017-001"
EXPECTED_EXECUTED_AT = "2025-07-01T00:06:31"
APPLICATION_ID = "APP_2025_DA_017"
INSTANCE_ID = "AINST-2025-DA017-01"
RETENTION_EVENT_ID = "REVT-DA017-EXP-01"

def _db_path(ws, system_name, baseline=False):
    filename = "state.db.pinned_backup" if baseline else "state.db"
    return Path(ws).parent / "system" / system_name / filename

def _local_datetime(value):
    if value is None:
        return None
    parsed = datetime.fromisoformat(str(value).strip().replace("Z", "+00:00"))
    if parsed.tzinfo is not None:
        parsed = parsed.astimezone(ZoneInfo("Asia/Shanghai")).replace(tzinfo=None)
    return parsed

def _same_time(actual, expected):
    try:
        return _local_datetime(actual) == _local_datetime(expected)
    except (TypeError, ValueError):
        return False

def _rows(connection, sql, params=()):
    return connection.execute(sql, params).fetchall()

def check_revoke_task_execution_recorded(ws):
    access_path = _db_path(ws, "cmb_access_control")
    retention_path = _db_path(ws, "cmb_retention_service")
    if not access_path.exists() or not retention_path.exists():
        return {"score": 0, "detail": "访问控制或留存与销毁系统数据库不存在"}
    with sqlite3.connect(access_path) as connection:
        connection.row_factory = sqlite3.Row
        row = connection.execute("SELECT * FROM revoke_tasks WHERE revoke_task_id=?", (TARGET_TASK_ID,)).fetchone()
    with sqlite3.connect(retention_path) as connection:
        connection.row_factory = sqlite3.Row
        event = connection.execute("SELECT * FROM retention_events WHERE event_id=?", (RETENTION_EVENT_ID,)).fetchone()
    if row is None:
        return {"score": 0, "detail": "目标到期回收任务不存在"}
    evidence = str(row["evidence_uri"] or "").strip()
    traceable = (
        event is not None
        and event["instance_id"] == INSTANCE_ID
        and event["event_type"] == "ACCESS_EXPIRED"
        and event["processed_status"] == "PROCESSED"
        and _same_time(event["event_at"], "2025-06-30T23:59:00")
        and _same_time(event["processed_at"], EXPECTED_EXECUTED_AT)
        and RETENTION_EVENT_ID.lower() in evidence.lower()
    )
    ok = (
        row["grant_id"] == TARGET_GRANT_ID
        and row["status"] == "succeeded"
        and row["trigger_type"] == "grant_expiry"
        and _same_time(row["scheduled_at"], "2025-06-30T23:59:00")
        and _same_time(row["executed_at"], EXPECTED_EXECUTED_AT)
        and traceable
        and row["attempt_count"] == 1
        and row["last_error"] is None
    )
    if ok:
        return {"score": 1, "detail": "目标到期回收任务已按实际处理时刻成功登记，证据可追溯到真实留存事件"}
    return {"score": 0, "detail": f"目标回收任务后态或证据不可追溯: {dict(row)}"}

def check_main_grant_revoked_with_audit(ws):
    path = _db_path(ws, "cmb_access_control")
    baseline = _db_path(ws, "cmb_access_control", baseline=True)
    if not path.exists() or not baseline.exists():
        return {"score": 0, "detail": "访问控制当前库或基线库不存在"}
    with sqlite3.connect(path) as current, sqlite3.connect(baseline) as before:
        current.row_factory = sqlite3.Row
        grant = current.execute("SELECT grant_status,revoked_at,updated_at FROM user_grants WHERE grant_id=?", (TARGET_GRANT_ID,)).fetchone()
        old_events = before.execute("SELECT COUNT(*) FROM grant_audit_events WHERE grant_id=?", (TARGET_GRANT_ID,)).fetchone()[0]
        events = current.execute("SELECT event_type,event_at,source_system,event_detail FROM grant_audit_events WHERE grant_id=? ORDER BY event_at,grant_event_id", (TARGET_GRANT_ID,)).fetchall()
        task = current.execute("SELECT evidence_uri FROM revoke_tasks WHERE revoke_task_id=?", (TARGET_TASK_ID,)).fetchone()
    if grant is None or task is None:
        return {"score": 0, "detail": "目标授权或目标任务不存在"}
    evidence = str(task["evidence_uri"] or "").strip()
    revoked = [event for event in events if event["event_type"] == "revoked" and _same_time(event["event_at"], EXPECTED_EXECUTED_AT) and event["source_system"] == "cmb_access_control" and evidence and evidence in event["event_detail"]]
    ok = (grant["grant_status"] == "revoked" and _same_time(grant["revoked_at"], EXPECTED_EXECUTED_AT) and _same_time(grant["updated_at"], EXPECTED_EXECUTED_AT) and len(events) == old_events + 1 and len(revoked) == 1)
    if ok:
        return {"score": 1, "detail": "主授权已回收，且仅新增一条与回收证据一致的审计事件"}
    return {"score": 0, "detail": f"主授权或审计后态不正确: grant={dict(grant)}, event_count={len(events)}, matching_revoked={len(revoked)}"}

def check_other_access_records_unchanged(ws):
    path = _db_path(ws, "cmb_access_control")
    baseline = _db_path(ws, "cmb_access_control", baseline=True)
    if not path.exists() or not baseline.exists():
        return {"score": 0, "detail": "访问控制当前库或基线库不存在"}
    with sqlite3.connect(path) as current, sqlite3.connect(baseline) as before:
        current_grants = _rows(current, "SELECT * FROM user_grants WHERE application_id=? AND grant_id<>? ORDER BY grant_id", (APPLICATION_ID, TARGET_GRANT_ID))
        baseline_grants = _rows(before, "SELECT * FROM user_grants WHERE application_id=? AND grant_id<>? ORDER BY grant_id", (APPLICATION_ID, TARGET_GRANT_ID))
        current_tasks = _rows(current, "SELECT rt.* FROM revoke_tasks rt JOIN user_grants ug ON ug.grant_id=rt.grant_id WHERE ug.application_id=? AND rt.revoke_task_id<>? ORDER BY rt.revoke_task_id", (APPLICATION_ID, TARGET_TASK_ID))
        baseline_tasks = _rows(before, "SELECT rt.* FROM revoke_tasks rt JOIN user_grants ug ON ug.grant_id=rt.grant_id WHERE ug.application_id=? AND rt.revoke_task_id<>? ORDER BY rt.revoke_task_id", (APPLICATION_ID, TARGET_TASK_ID))
    if current_grants == baseline_grants and current_tasks == baseline_tasks:
        return {"score": 1, "detail": "同申请的其他授权和回收任务均未改变"}
    return {"score": 0, "detail": "同申请的其他授权或回收任务被修改"}

def check_retention_system_unchanged(ws):
    path = _db_path(ws, "cmb_retention_service")
    baseline = _db_path(ws, "cmb_retention_service", baseline=True)
    if not path.exists() or not baseline.exists():
        return {"score": 0, "detail": "留存与销毁当前库或基线库不存在"}
    checks = [("access_instances", "instance_id=?", (INSTANCE_ID,), "instance_id"), ("object_catalog", "instance_id=?", (INSTANCE_ID,), "object_id"), ("temporary_objects", "instance_id=?", (INSTANCE_ID,), "object_detail_id"), ("retention_events", "instance_id=?", (INSTANCE_ID,), "event_id"), ("destruction_certificates", "instance_id=?", (INSTANCE_ID,), "certificate_id"), ("retained_records", "application_id=?", (APPLICATION_ID,), "retained_record_id")]
    with sqlite3.connect(path) as current, sqlite3.connect(baseline) as before:
        for table, where, params, order_by in checks:
            sql = f"SELECT * FROM {table} WHERE {where} ORDER BY {order_by}"
