def check_timing_review_post_state(workspace):
    with _connect(workspace) as connection:
        usage_rows = connection.execute(
            "SELECT usage_id, review_status FROM work_order_usage WHERE review_status='TIMING_DIFFERENCE'"
        ).fetchall()
        actual_usage = {row["usage_id"] for row in usage_rows}
        if actual_usage != TARGET_IDS:
            return {"score": 0, "detail": f"TIMING_DIFFERENCE usage set was {sorted(actual_usage)}"}
        if not _reviews_exist(connection):
            return {"score": 0, "detail": "The Maximo review audit table was not created."}
        review_rows = connection.execute(
            "SELECT usage_id, disposition FROM work_order_reviews WHERE disposition='TIMING_DIFFERENCE'"
        ).fetchall()
        actual_reviews = {row["usage_id"] for row in review_rows}
        if actual_reviews != TARGET_IDS:
            return {"score": 0, "detail": f"Timing-difference audit set was {sorted(actual_reviews)}"}
    return {"score": 1, "detail": "Exactly the four qualifying cutoff items have matching timing-difference usage and audit dispositions."}


def _rationale_is_sufficient(note):
    text = " ".join(str(note or "").lower().replace("-", " ").replace("_", " ").split())
    has_q3_cutoff = (
        ("september" in text and ("30" in text or "cutoff" in text or "quarter" in text or "q3" in text))
        or ("q3" in text and ("cutoff" in text or "complete" in text))
    )
    has_october_posting = ("october" in text or re.search(r"\b2025\s+10\s+\d{1,2}\b", text) is not None) and ("accrual" in text or "post" in text or "sap" in text)
    has_timing_conclusion = "timing" in text and (
        "not omitted" in text
        or "no omission" in text
        or "rather than omitted" in text
        or "controlled" in text
        or "difference" in text
    )
    return has_q3_cutoff and has_october_posting and has_timing_conclusion


def check_timing_review_audit_rationale(workspace):
    with _connect(workspace) as connection:
        if not _reviews_exist(connection):
            return {"score": 0, "detail": "No Maximo review audit rows exist."}
        placeholders = ",".join("?" for _ in TARGET_IDS)
        rows = connection.execute(
            f"SELECT usage_id, reviewer_person_id, disposition, review_note, reviewed_at FROM work_order_reviews WHERE usage_id IN ({placeholders})",
            tuple(sorted(TARGET_IDS)),
        ).fetchall()
    if {row["usage_id"] for row in rows} != TARGET_IDS:
        return {"score": 0, "detail": "One or more target audit rows are missing."}
    failures = []
    for row in rows:
        if row["disposition"] != "TIMING_DIFFERENCE" or not str(row["reviewer_person_id"] or "").strip():
            failures.append(row["usage_id"])
            continue
        try:
            datetime.fromisoformat(str(row["reviewed_at"]).replace("Z", "+00:00"))
        except (TypeError, ValueError):
            failures.append(row["usage_id"])
            continue
        if not _rationale_is_sufficient(row["review_note"]):
            failures.append(row["usage_id"])
    if failures:
        return {"score": 0, "detail": f"Incomplete audit metadata or cutoff rationale for {sorted(failures)}"}
    return {"score": 1, "detail": "All four audit rows contain reviewer metadata and a sufficient cutoff-timing rationale."}


def check_protected_source_fields(workspace):
    columns = (
        "work_order_batch_key, asset_id, period_id, facility_id, recipient_cost_center_id, "
        "completed_order_count, labor_minutes, work_status, completion_date, sap_accrual_posting_date, "
        "is_duplicate, duplicate_of_usage_id, source_record_key"
    )
    ids = tuple(sorted(PROTECTED_USAGE))
    placeholders = ",".join("?" for _ in ids)
    with _connect(workspace) as connection:
        rows = connection.execute(
            f"SELECT usage_id, {columns} FROM work_order_usage WHERE usage_id IN ({placeholders})",
            ids,
        ).fetchall()
        history_rows = connection.execute(
            f"SELECT status_event_id, usage_id, from_status, to_status, event_timestamp, changed_by_person_id, change_reason_code, source_event_key "
            f"FROM work_order_status_history WHERE usage_id IN ({placeholders})",
            ids,
        ).fetchall()
    actual_usage = {row["usage_id"]: tuple(row[column.strip()] for column in columns.split(",")) for row in rows}
    if actual_usage != PROTECTED_USAGE:
        changed = sorted(set(PROTECTED_USAGE) | set(actual_usage))
        return {"score": 0, "detail": f"A protected source field or record changed in the reviewed population: {changed}"}
    actual_history = {tuple(row) for row in history_rows}
    if actual_history != PROTECTED_HISTORY:
        return {"score": 0, "detail": "Protected status-history evidence was changed, removed, or added."}
    return {"score": 1, "detail": "Protected usage fields and status-history evidence remain unchanged."}


def check_other_exception_treatments(workspace):
    ids = tuple(sorted(EXCEPTION_STATUSES))
    placeholders = ",".join("?" for _ in ids)
    with _connect(workspace) as connection:
        rows = connection.execute(
            f"SELECT usage_id, review_status FROM work_order_usage WHERE usage_id IN ({placeholders})",
            ids,
        ).fetchall()
        actual = {row["usage_id"]: row["review_status"] for row in rows}
        if actual != EXCEPTION_STATUSES:
            return {"score": 0, "detail": f"Established exception treatments changed: {actual}"}
        if _reviews_exist(connection):
            review_count = connection.execute(
                f"SELECT COUNT(*) FROM work_order_reviews WHERE usage_id IN ({placeholders})",
                ids,
            ).fetchone()[0]
            if review_count:
                return {"score": 0, "detail": "An audit review was written to a protected exception record."}
    return {"score": 1, "detail": "Canceled, reopened, duplicate, and orphan exception treatments remain untouched."}

import sqlite3
import re
from pathlib import Path
from datetime import datetime


def _mes_db(ws):
    return Path(ws).resolve().parent / "system" / "siemens_opcenter_mes" / "state.db"


def _norm(value):
    return "" if value is None else " ".join(str(value).strip().split()).casefold()


def _iso(value):
    try:
        return datetime.fromisoformat(str(value).replace("Z", "+00:00"))
    except (TypeError, ValueError):
        return None


def check_rework_disposition(ws):
    """Check the unique newly persisted disposition without requiring a timestamp format."""
    db = _mes_db(ws)
    with sqlite3.connect(db) as con:
        con.row_factory = sqlite3.Row
        table = con.execute(
            "SELECT name FROM sqlite_master WHERE type='table' AND name='rework_dispositions'"
        ).fetchone()
        if table is None:
            return {"score": 0, "detail": "rework_dispositions table is absent"}
        rows = con.execute(
            "SELECT * FROM rework_dispositions WHERE order_id=? AND serial_cohort_id=? "
            "ORDER BY disposition_id",
            ("MO_250208_03", "COHORT_FAIL_001"),
        ).fetchall()
    if len(rows) != 1:
        return {"score": 0, "detail": f"expected exactly one target disposition, found {len(rows)}"}
    row = rows[0]
    required = {
        "order_id": "MO_250208_03",
        "serial_cohort_id": "COHORT_FAIL_001",
        "failed_operation_code": "OP20",
        "disposition": "TRANSFER_TO_REWORK",
        "retest_operation_code": "OP50",
    }
    bad = []
    for key, expected in required.items():
        if _norm(row[key]) != _norm(expected):
            bad.append(f"{key}={row[key]!r}, expected {expected!r}")
    allowed_operator_ids = {_norm("陆清和"), _norm("SZ-CY-OP-031")}
    if _norm(row["operator_id"]) not in allowed_operator_ids:
        bad.append(
            f"operator_id={row['operator_id']!r}, expected 陆清和 or MES ID SZ-CY-OP-031"
        )
    reason = _norm(row["disposition_reason"])
    for phrase in ("op20", "op30", "返工"):
        if phrase not in reason:
            bad.append(f"disposition_reason missing {phrase}")
    if _iso(row["disposition_time"]) is None:
        bad.append("disposition_time is not an ISO-8601 timestamp")
    if bad:
        return {"score": 0, "detail": "; ".join(bad)}
    return {"score": 1, "detail": "target disposition fields and retest linkage are correct"}


def check_qms_open_failure_gap_answer(ws):
    answer = Path(ws) / "answer.md"
    if not answer.exists():
        return {"score": 0, "detail": "answer.md is absent"}
    text = " ".join(answer.read_text(encoding="utf-8", errors="ignore").split())
    folded = text.casefold()
    has_target = "gap-250208-004" in folded or (
        ("测试失败" in text or "test_failure" in folded) and "缺口" in text
    )
    has_open = "open" in folded or "未关闭" in text
    owner_pattern = (
        r"(?:责任(?:归属)?系统|归属(?:的)?责任系统|缺口归属).{0,50}"
        r"(?:siemens(?:[_ ]+opcenter)?[_ ]+mes|mes)"
    )
    has_mes_owner = re.search(owner_pattern, folded, flags=re.IGNORECASE) is not None
    missing = []
    if not has_target:
        missing.append("target test-failure gap")
    if not has_open:
        missing.append("open/unclosed status")
    if not has_mes_owner:
        missing.append("MES responsibility attribution")
    if missing:
        return {"score": 0, "detail": "answer missing " + ", ".join(missing)}
    return {"score": 1, "detail": "answer reports the open test-failure gap and MES responsibility"}

def check_original_history_unchanged(ws):
    db = _mes_db(ws)
    with sqlite3.connect(db) as con:
        con.row_factory = sqlite3.Row
        rows = con.execute(
            "SELECT archive_fact_id, order_id, operation_code, serial_cohort_id, serial_count, "
            "archived_serial_count, archive_status, test_result, operator_id, equipment_id, "
            "inbound_time, outbound_time, material_lot_no, component_date_code, record_class, "
            "fact_type, event_date, source_system FROM operation_archive_facts "
            "WHERE order_id=? AND serial_cohort_id=? ORDER BY archive_fact_id",
            ("MO_250208_03", "COHORT_FAIL_001"),
        ).fetchall()
    expected = [
        ("AF_25020803_FAIL_0020", "OP20", "不合格", "2025-02-13T08:14:02", "2025-02-13T08:28:11", "FIRST_PASS"),
        ("AF_25020803_FAIL_0030", "OP30", "合格", "2025-02-13T08:35:24", "2025-02-13T08:47:50", "FIRST_PASS"),
    ]
    actual = [(r["archive_fact_id"], r["operation_code"], r["test_result"], r["inbound_time"], r["outbound_time"], r["record_class"]) for r in rows]
    if actual != expected:
        return {"score": 0, "detail": f"original history changed: {actual!r}"}
    return {"score": 1, "detail": "original OP20 failure and OP30 downstream facts are unchanged"}
